import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"즉시 답변 및 키워드 단축 명령","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/instant-answers.md","filePath":"ko-KR/user-guide/instant-answers.md","lastUpdated":1787480649000}'),d={name:"ko-KR/user-guide/instant-answers.md"};function r(n,e,i,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="즉시-답변-및-키워드-단축-명령" tabindex="-1">즉시 답변 및 키워드 단축 명령 <a class="header-anchor" href="#즉시-답변-및-키워드-단축-명령" aria-label="Permalink to &quot;즉시 답변 및 키워드 단축 명령&quot;">​</a></h1><p>일부 결과는 파일 검색을 기다리지 않고 입력하는 즉시 나타납니다 — 항상 활성화되어 있거나, 실제 쿼리를 입력하기 전에 짧은 키워드로 게이트되어 있습니다(브라우저 기록 검색처럼 큰 기능이 관련 없는 모든 키 입력마다 주목을 끌지 않도록 하기 위함입니다). 키워드로 게이트된 대부분의 기능은 <strong>설정 → 플러그인 → 구성</strong>에서 키워드를 설정할 수 있습니다.</p><h2 id="항상-활성화" tabindex="-1">항상 활성화 <a class="header-anchor" href="#항상-활성화" aria-label="Permalink to &quot;항상 활성화&quot;">​</a></h2><p>이들은 키워드가 필요 없습니다 — 입력한 내용이 각자의 패턴과 일치하면 즉시 활성화됩니다.</p><h3 id="계산기" tabindex="-1">계산기 <a class="header-anchor" href="#계산기" aria-label="Permalink to &quot;계산기&quot;">​</a></h3><p>수식을 직접 입력하면 결과가 실시간으로 나타나며, <strong>Enter</strong>를 누르면 클립보드로 복사됩니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12 * (4 + 3)</span></span></code></pre></div><p>명시적인 진법 변환도 지원됩니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>255 to hex</span></span>
<span class="line"><span>0xFF to dec</span></span></code></pre></div><h3 id="환경-변수" tabindex="-1">환경 변수 <a class="header-anchor" href="#환경-변수" aria-label="Permalink to &quot;환경 변수&quot;">​</a></h3><ul><li><code>%NAME%</code>은 특정 변수를 펼쳐 보여줍니다(<code>%PATH%</code> 같은 다중 경로 변수는 경로별로 하나씩 항목이 나뉩니다).</li><li><code>%partial</code>은 <code>partial</code>과 일치하는 모든 변수 이름을 퍼지 매칭으로 나열합니다.</li></ul><h3 id="명령-실행하기" tabindex="-1">명령 실행하기 <a class="header-anchor" href="#명령-실행하기" aria-label="Permalink to &quot;명령 실행하기&quot;">​</a></h3><ul><li><code>#&lt;command&gt;</code>는 명령 프롬프트 창을 열고 <code>&lt;command&gt;</code>를 <strong>관리자 권한으로</strong> 실행합니다.</li><li><code>$&lt;command&gt;</code>는 명령 프롬프트 창을 열고 <code>&lt;command&gt;</code>를 일반적으로 실행합니다.</li></ul><h3 id="순수-url" tabindex="-1">순수 URL <a class="header-anchor" href="#순수-url" aria-label="Permalink to &quot;순수 URL&quot;">​</a></h3><p><code>http://</code>/<code>https://</code> 주소를 입력하거나 붙여넣으면 Lertaro가 이를 바로 열도록 제안합니다.</p><h2 id="키워드로-트리거-내장-설정-가능한-접두사" tabindex="-1">키워드로 트리거 (내장, 설정 가능한 접두사) <a class="header-anchor" href="#키워드로-트리거-내장-설정-가능한-접두사" aria-label="Permalink to &quot;키워드로 트리거 (내장, 설정 가능한 접두사)&quot;">​</a></h2><p>키워드, 공백, 그다음 쿼리를 입력하세요. 각 키워드는 기본적으로 짧은 접두사로 설정되어 있지만, 자주 입력하는 다른 무언가와 충돌한다면 해당 플러그인 자체의 <strong>구성</strong> 대화상자에서 독립적으로 변경할 수 있습니다.</p><table tabindex="0"><thead><tr><th>키워드 (기본값)</th><th>플러그인</th><th>검색 대상</th></tr></thead><tbody><tr><td><code>ps</code></td><td>Process Manager</td><td>이름, PID, 창 제목으로 실행 중인 프로세스를 검색합니다(퍼지/병음 매칭도 지원) — 하나를 선택하면 종료합니다.</td></tr><tr><td><code>win</code></td><td>Window Switcher</td><td>현재 열려 있고 전환 가능한 창(Alt+Tab이 보여주는 것과 동일한 집합)을 제목, 프로세스 이름, PID로 검색합니다. 하나를 선택하면 전면으로 가져옵니다.</td></tr><tr><td><code>bm</code></td><td>Browser Data</td><td>해당 플러그인 자체 설정에서 추가한 Chrome/Chromium 계열 및 Firefox 계열 브라우저 프로필의 북마크와 기록입니다.</td></tr><tr><td><code>set</code></td><td>Core Extensions</td><td>앱의 모든 설정을 이름으로 퍼지 매칭합니다 — 하나를 선택하면 강조 표시된 상태로 설정의 해당 항목으로 바로 이동합니다. <code>set</code>만 입력하면(뒤에 아무것도 없이) 모든 설정을 나열합니다.</td></tr><tr><td><code>flow</code></td><td>Flow Launcher Bridge</td><td>로드된 모든 Flow.Launcher 플러그인과 해당 트리거 키워드를 나열합니다(공백 후 필터링 가능). 플러그인 설정은 <strong>설정 → 플러그인</strong>에서 직접 통합 관리됩니다.</td></tr></tbody></table><p>Window Switcher는 기본적으로 각 창의 실제 콘텐츠 실시간 썸네일을 아이콘으로 보여주며, 이는 백그라운드에서 캡처되므로 입력 속도가 느려지지 않습니다 — 일반 앱 아이콘이 먼저 즉시 표시되고, 준비되면 썸네일이 서서히 나타납니다. <strong>설정 → 플러그인 → Window Switcher → 구성</strong>에서 <strong>창 콘텐츠를 아이콘으로 표시</strong>를 끄면 이 캡처를 완전히 건너뛰고 항상 앱 아이콘을 사용합니다. 진짜 배타적 전체 화면으로 실행 중인 창(대부분의 게임은 기본적으로 이 대신 테두리 없는 창 모드를 사용하며, 이는 문제없이 처리됩니다)은 이 방식으로 캡처할 수 없으며 항상 앱 아이콘으로 대체됩니다.</p><p>Browser Data는 북마크와 기록을 독립적으로 인덱싱합니다 — <strong>북마크 인덱싱</strong>과 <strong>기록 인덱싱</strong>은 <strong>설정 → 플러그인 → Browser Data → 구성</strong>에서 별도의 토글이므로, 북마크는 계속 검색하면서 기록만 끄거나(기록은 북마크보다 훨씬 커지는 경향이 있습니다) 그 반대로 할 수 있습니다.</p><h2 id="웹-검색" tabindex="-1">웹 검색 <a class="header-anchor" href="#웹-검색" aria-label="Permalink to &quot;웹 검색&quot;">​</a></h2><p>Web Search는 여러 검색 엔진/사이트에 대한 기본 키워드를 함께 제공합니다 — <code>bd</code>(바이두), <code>g</code>(Google), <code>bing</code>(Bing), <code>gh</code>(GitHub), <code>wiki</code>(위키백과), <code>yt</code>(YouTube) — 그리고 <strong>설정 → 플러그인 → Web Search → 구성</strong>에서 각각 이름, 키워드, 아이콘, URL 템플릿을 지정하여 항목을 추가, 편집, 완전히 삭제할 수 있습니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>g lertaro github</span></span></code></pre></div><p>는 브라우저에서 &quot;lertaro github&quot;에 대한 Google 검색을 엽니다.</p><h2 id="번역" tabindex="-1">번역 <a class="header-anchor" href="#번역" aria-label="Permalink to &quot;번역&quot;">​</a></h2><p>번역 플러그인의 기본 키워드는 <code>tr</code>입니다. 뒤에 텍스트를 입력하면 현재 Lertaro 인터페이스에서 선택한 언어로 번역합니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tr hello</span></span></code></pre></div><p>결과는 비동기로 표시됩니다. <strong>Enter</strong> 키를 누르거나 클릭하면 복사할 수 있습니다. 번역할 텍스트는 Microsoft Translator로 전송되므로 인터넷 연결이 필요합니다. 대상 언어는 App의 현재 언어 설정입니다. 키워드는 <strong>설정 → 플러그인 → 번역 → 구성</strong>에서 변경할 수 있습니다.</p><h2 id="file-filters" tabindex="-1">File Filters <a class="header-anchor" href="#file-filters" aria-label="Permalink to &quot;File Filters&quot;">​</a></h2><p><strong>설정 → 플러그인 → File Filters → 구성</strong>에서 완전히 구성되는, 자체 규칙 아래 특정 폴더를 인덱싱합니다. 각 규칙은 자체 <strong>대상 폴더</strong> 목록(재귀적으로 스캔), <strong>확장자 / 패턴</strong> 필드(예: <code>*.exe;*.lnk</code> — <code>;</code> 또는 <code>,</code>로 구분된 여러 패턴이 모두 매칭됩니다. 기본값 <code>*</code>는 모든 파일과 일치합니다), 결과 설명에 표시되는 선택적인 <strong>필터 이름</strong>을 가집니다. 하위 폴더는 패턴과 무관하게 항상 포함됩니다 — 패턴으로 필터링되는 것은 파일뿐입니다.</p><p><strong>바로가기 키워드</strong>를 추가하면 위의 내장 키워드와 마찬가지로, 일반 인덱스에 항상 섞어 넣는 대신 규칙의 매칭 결과를 접두사 뒤로 게이트할 수 있습니다.</p><h2 id="완전히-커스텀-직접-키워드-정의" tabindex="-1">완전히 커스텀 (직접 키워드 정의) <a class="header-anchor" href="#완전히-커스텀-직접-키워드-정의" aria-label="Permalink to &quot;완전히 커스텀 (직접 키워드 정의)&quot;">​</a></h2><h3 id="커스텀-명령" tabindex="-1">커스텀 명령 <a class="header-anchor" href="#커스텀-명령" aria-label="Permalink to &quot;커스텀 명령&quot;">​</a></h3><p><strong>설정 → 플러그인 → Custom Commands → 구성</strong>에서 완전히 구성되는, 외부 프로그램을 실행하는 여러분만의 <code>&lt;keyword&gt; &lt;args&gt;</code> 명령을 정의합니다. 명령의 매개변수 템플릿은 위치 기반 플레이스홀더(공백으로 구분된 각 인수에 대한 <code>%s1</code>, <code>%s2</code>, ...)와 전체 나머지 플레이스홀더(키워드 뒤에 입력한 모든 것에 대한 <code>%s</code>)를 지원합니다.</p><p>각 명령에는 <strong>빠른 탐색에 표시</strong> 체크박스도 있습니다(기본값 꺼짐) — 켜면 해당 명령이 <a href="./hotkeys.html#빠른-탐색-마우스">빠른 탐색</a> 메뉴의 루트에도 자체 항목으로 나열되어, 키워드를 전혀 입력하지 않고도 클릭할 수 있습니다. <strong>빠른 탐색 하위 메뉴</strong> 필드는 루트 대신 이름 붙은 하위 메뉴 아래에 중첩시킵니다 — 여러 단계로 중첩하려면 <code>/</code>를 사용하세요(예: 2단계 하위 메뉴를 위한 <code>Tools/Network</code>). 비워두면 명령이 최상위 레벨에 유지됩니다. 이 방식으로 표시된 명령은 여기서 <code>%s1</code>/<code>%s</code>에 대입할 입력된 인수 텍스트가 없으므로, 구성된 매개변수를 그대로 사용하여 실행됩니다.</p><hr><p>이 페이지의 어떤 플러그인도 필수가 아닙니다 — 각각은 키보드 공간을 두고 경쟁하는 것을 원하지 않는다면 <a href="./settings/plugins.html">설정 → 플러그인</a>에서 독립적으로 비활성화할 수 있으며, <a href="./search-syntax.html">검색 문법</a>은 그 밖의 모든 것(파일, 폴더, 애플리케이션)에 사용되는, 별개로 항상 활성화되어 있는 퍼지 쿼리 언어를 다룹니다.</p>`,37)])])}const u=t(d,[["render",r]]);export{g as __pageData,u as default};
